<?php get_header(); $q=kzfr_filter_value('q'); $underwriters=kzfr_query('kzfr_underwriter',-1,['s'=>$q]); ?><div class="section-wrap section-space"><?php kzfr_page_intro('STATION SUPPORTERS','Underwriters','Meet a selection of businesses and organizations listed as supporters on KZFR’s public site.'); ?><div class="archive-callout"><div><strong>Underwriting information</strong><p>Explore how local underwriting supports independent community radio.</p></div><a class="button button-dark" href="<?php echo kzfr_url('underwrite'); ?>">Become an underwriter </a></div><form class="filter-bar" method="get" role="search"><input type="hidden" name="design" value="<?php echo esc_attr(kzfr_current_design()); ?>"><div class="field field-grow"><label for="underwriter-search">Find a supporter</label><input type="search" name="q" id="underwriter-search" value="<?php echo esc_attr($q); ?>" placeholder="Business or organization name"></div><button class="button button-dark">Search</button><a href="<?php echo kzfr_url('underwriters'); ?>">Reset</a></form><div class="underwriter-grid"><?php while($underwriters->have_posts()): $underwriters->the_post(); ?><article class="underwriter-card"><span class="underwriter-mark" aria-hidden="true"><?php echo esc_html(mb_substr(get_the_title(),0,1)); ?></span><h2><?php the_title(); ?></h2><?php kzfr_link(kzfr_meta('url'),'Visit website'); ?></article><?php endwhile; wp_reset_postdata(); ?></div><?php if(!$underwriters->found_posts): ?><p>No matching supporters in this preview.</p><?php endif; ?><aside class="source-note">Public listing snapshot, not a statement of a current agreement. <a href="https://www.kzfr.org/underwriters">See KZFR’s official underwriter directory </a>.</aside></div><?php get_footer(); ?>
